import type { AtlasCampaignCollection, AtlasHistoryCollection, AtlasNeighborhood, AtlasOverview, AtlasRecordDetail, AtlasRecordLibraryResult, AtlasWorkflowSummary, ProviderReadiness } from "../../src/contracts/v1";

const digest = (value: string) => value.repeat(64);
export const headRevision = { revision_id: "revision_two", ordinal: 2, tree_digest: digest("a") } as const;
export const oldRevision = { revision_id: "revision_one", ordinal: 1, tree_digest: digest("b") } as const;
export const binding = { campaign_id: "campaign_atlas", viewed_revision: headRevision, head_revision: headRevision } as const;
export const readinessUnavailable: ProviderReadiness = { contract_name: "provider_readiness_response", contract_version: 1, provider_configured: true, provider_available: false, consent_current: false, consent_identity_digest: digest("9"), ai_available: false };

export const campaigns: AtlasCampaignCollection = { contract_name: "atlas_campaign_collection", contract_version: 1, campaigns: [{ campaign_id: "campaign_atlas", campaign_name: "Synthetic Atlas", adapter_id: "mothership", recovery_state: "ready", head_revision: headRevision, projected_revision: headRevision }] };
export const overview: AtlasOverview = { contract_name: "atlas_overview", contract_version: 1, binding, campaign_name: "Synthetic Atlas", adapter_id: "mothership", record_count: 2, edge_occurrence_count: 1, approved_revision_count: 6, facets: { record_types: [{ value: "npc", count: 1 }, { value: "ship", count: 1 }], authorities: [{ value: "canon", count: 1 }, { value: "preparation", count: 1 }], statuses: [{ value: "canon", count: 1 }, { value: "accepted", count: 1 }] } };
export const recordItem = { record_id: "record-one", record_type: "npc", name: "Station Keeper", raw_status: { classification: "known", value: "canon" }, authority: "canon", summary: "Keeps the synthetic station.", content_digest: digest("c") } as const;
export const legacyItem = { record_id: "record-two", record_type: "ship", name: "Legacy Ship", raw_status: { classification: "known", value: "accepted" }, authority: "preparation", summary: "", content_digest: digest("d") } as const;
export const records: AtlasRecordLibraryResult = { contract_name: "atlas_record_library_result", contract_version: 1, binding, normalized_query: "", filters: { record_types: [], authorities: [], statuses: [] }, limit: 50, sort: "record_id", total: 2, items: [recordItem, legacyItem], facets: overview.facets, next_cursor: "cursor_next", previous_cursor: null };
export const detail: AtlasRecordDetail = { contract_name: "atlas_record_detail", contract_version: 1, binding, record: { ...recordItem, content: "# Station Keeper\n\nSafe [brief](https://example.test/brief). Unsafe [trap](javascript:alert(1)).\n\n<script>not executable</script>" } };
export const neighborhood: AtlasNeighborhood = { contract_name: "atlas_depth_1_neighborhood", contract_version: 1, binding, depth: 1, limit: 50, sort: "source_occurrence_edge", focus: recordItem, neighbors: [legacyItem], edges: [{ edge_id: `edge_${digest("e")}`, occurrence_order: 1, source_record_id: "record-one", target_record_id: "record-two", relationship: "knows", state: "current", context: "Synthetic edge." }], total_edges: 1, next_cursor: null, previous_cursor: null };

const historyEntry = (ordinal: number) => ({ revision: { revision_id: `revision_${ordinal}`, ordinal, tree_digest: digest(String(ordinal)) }, parent_revision_id: ordinal === 1 ? null : `revision_${ordinal - 1}`, change_digest: digest("f"), affected_records: [{ record_id: "record-one", link_revision_id: `revision_${ordinal}` }], changes: [{ record_id: "record-one", change_kind: ordinal === 1 ? "added" as const : "content_changed" as const, link_revision_id: `revision_${ordinal}`, before_content_digest: ordinal === 1 ? null : digest("b"), after_content_digest: digest("c"), before_status: ordinal === 1 ? null : { classification: "known" as const, value: "canon" as const }, after_status: { classification: "known" as const, value: "canon" as const }, from_authority: ordinal === 1 ? null : "canon" as const, to_authority: "canon" as const }], proposal_id: ordinal === 2 ? "proposal_one" : null, proposal_version: ordinal === 2 ? 1 : null });
export const newestFiveHistory: AtlasHistoryCollection = { contract_name: "atlas_approved_history_collection", contract_version: 1, binding, subject_record_id: null, limit: 5, sort: "revision_ordinal", total: 6, entries: [6, 5, 4, 3, 2].map(historyEntry), next_cursor: "cursor_older", previous_cursor: null };
export const recordHistory: AtlasHistoryCollection = { contract_name: "atlas_approved_history_collection", contract_version: 1, binding, subject_record_id: "record-one", limit: 50, sort: "revision_ordinal", total: 2, entries: [historyEntry(1), historyEntry(2)], next_cursor: null, previous_cursor: null };
export const fullHistory: AtlasHistoryCollection = { ...recordHistory, subject_record_id: null };
export const workflow: AtlasWorkflowSummary = { contract_name: "atlas_workflow_summary", contract_version: 1, binding, draft_generation_count: 1, proposal_counts: { draft: 1, rejected: 0, conflict: 0, published: 1, quarantined: 0 }, active_session: null };
